<script setup lang="ts">
import {ref,watch,nextTick} from 'vue'
import type {AdminUserDetail} from '@/api/admin-users'
const props=defineProps<{open:boolean;user:AdminUserDetail|null;loading:boolean;error:string}>(),emit=defineEmits<{close:[];status:[user:AdminUserDetail];audit:[id:string]}>(),dialog=ref<HTMLDialogElement>()
watch(()=>props.open,async open=>{await nextTick();if(open&&!dialog.value?.open)dialog.value?.showModal();if(!open)dialog.value?.close()})
</script>
<template><dialog ref="dialog" class="users-dialog" aria-labelledby="admin-user-detail-title" @cancel.prevent="emit('close')"><header><div><h2 id="admin-user-detail-title">账号详情</h2><p class="muted">资料与账号状态</p></div><button aria-label="关闭账号详情" @click="emit('close')">×</button></header><p v-if="loading" role="status">正在加载账号…</p><p v-if="error" class="users-error" role="alert">{{error}}</p><template v-if="user"><dl class="users-facts"><div><dt>账号</dt><dd>{{user.username}}</dd></div><div><dt>昵称</dt><dd>{{user.displayName}}</dd></div><div><dt>用户 ID</dt><dd>{{user.id}}</dd></div><div><dt>角色</dt><dd>{{user.roles.includes('ADMIN')?'管理员':'学习者'}}</dd></div><div><dt>账号状态</dt><dd>{{user.enabled?'正常':'已停用'}}</dd></div><div><dt>注册时间</dt><dd>{{new Date(user.createdAt).toLocaleDateString('zh-CN')}}</dd></div><div><dt>邮箱</dt><dd>{{user.maskedEmail}}</dd></div><div><dt>邮箱验证</dt><dd>{{user.emailVerified?'已验证':'尚未验证'}}</dd></div></dl><p class="users-help">{{user.protectedAccount?'管理员账号受保护，本模块只提供查看。':'停用会限制登录与需要登录的操作，学习和留言记录保留。密码问题由用户在登录页自行验证邮箱重置。'}}</p><div class="users-actions"><button @click="emit('audit',user.id)">查看管理记录</button><button :disabled="user.protectedAccount" :class="{'users-danger':user.enabled}" @click="emit('status',user)">{{user.enabled?'停用账号':'恢复账号'}}</button></div></template></dialog></template>
